import { readFile, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
const require = createRequire(new URL('../tools/openapi/package.json', import.meta.url));
const { default: openapiTS, astToString } = require('openapi-typescript');
const schema = new URL('../openapi/atelier-api.json', import.meta.url);
const output = new URL('../src/app/core/api/generated/schema.ts', import.meta.url);
const generated =
  '// Generated by npm run api:generate from openapi/atelier-api.json. DO NOT EDIT.\n' +
  astToString(await openapiTS(JSON.parse(await readFile(schema, 'utf8'))));
if (process.argv.includes('--check')) {
  if ((await readFile(output, 'utf8')) !== generated) {
    throw new Error('OpenAPI types are stale. Run npm run api:generate and commit the result.');
  }
} else await writeFile(output, generated);
